/** @type {import('tailwindcss').Config} */
// Colours come from CSS variables in src/theme.css, generated by
// docs/design/palette.py. See DESIGN.md for the palette and its roles.
const STEPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];
const scale = (name) =>
  Object.fromEntries(STEPS.map((s) => [s, `rgb(var(--${name}-${s}) / <alpha-value>)`]));
const fgScale = (name) =>
  Object.fromEntries(STEPS.map((s) => [s, `rgb(var(--fg-${name}-${s}) / <alpha-value>)`]));
const role = (name) => `rgb(var(--role-${name}) / <alpha-value>)`;

// The step where each brand hex is pinned (docs/design/palette.py), so that
// plain `bg-ember` / `text-lagoon` give the exact brand colour.
const PINNED = { ink: 800, ember: 400, apricot: 300, cream: 100, dusk: 800, iris: 600,
                 lagoon: 400, lime: 100, jade: 500, coral: 500, orchid: 500 };
const withDefault = (name, make) => ({ ...make(name), DEFAULT: make(name)[PINNED[name]] });
const brand = Object.fromEntries(Object.keys(PINNED).map((n) => [n, withDefault(n, scale)]));

// Same aliases for text, on the text variable set (see DESIGN.md, Dark mode).
const NAMES = Object.keys(brand);
const fg = Object.fromEntries(NAMES.map((n) => [n, withDefault(n, fgScale)]));
const aliases = (b) => ({
  slate: b.ink, gray: b.ink, zinc: b.ink,
  blue: b.iris, indigo: b.iris, violet: b.iris,
  purple: b.orchid, fuchsia: b.orchid, pink: b.orchid,
  sky: b.lagoon, cyan: b.lagoon, teal: b.lagoon,
  emerald: b.jade, green: b.jade,
  red: b.coral, rose: b.coral,
  amber: b.apricot, yellow: b.apricot, orange: b.ember,
});
const roles = {
  bg: role("bg"), surface: role("surface"), "surface-muted": role("surface-muted"),
  line: role("border"), body: role("text"), muted: role("text-muted"),
  heading: role("heading"), primary: role("primary"), "on-primary": role("primary-text"),
  accent: role("accent"), "on-accent": role("accent-text"), link: role("link"),
  highlight: role("highlight"), focus: role("focus"),
};

export default {
  darkMode: "class",
  content: ["./index.html", "./src/**/*.{ts,tsx}"],
  theme: {
    extend: {
      colors: { ...brand, ...aliases(brand), ...roles },
      textColor: { ...fg, ...aliases(fg), ...roles },
      fontFamily: {
        sans: ['"Plus Jakarta Sans"', "ui-sans-serif", "system-ui", "sans-serif"],
        display: ['"Space Grotesk"', '"Plus Jakarta Sans"', "ui-sans-serif", "sans-serif"],
        mono: ['"JetBrains Mono"', "ui-monospace", "SFMono-Regular", "monospace"],
      },
      borderRadius: { card: "0.875rem" },
      boxShadow: {
        card: "0 1px 2px rgb(var(--dusk-950) / 0.06), 0 4px 16px rgb(var(--dusk-950) / 0.06)",
      },
    },
  },
  plugins: [],
};
